function solve(input) {
    let { stack, action, value, history } = input;

    if (action === "push") {
        history.push([...stack, value]);
        stack = [...stack, value];
    } else if (action === "pop") {
        if (stack.length > 0) {
            history.push([...stack]);
            stack = stack.slice(0, -1);
        }
    } else if (action === "rollback") {
        if (history.length > 0) {
            stack = history.pop();
        }
    }

    return { stack, history };
}

